          "medium": "您对孩子学业比较关心，但有时会不自觉传递焦虑。在考砸时容易情绪失控。建议把关注点从分数转移到学习习惯和方法上。",
          "low": "家庭目前是学业的第二战场，充满了高压和紧张。孩子背负双重压力，容易产生厌学情绪。建议立刻降低对分数的执念，先修复亲子关系。"
